all_items = []
counts = {c["id"]: 0 for c in categories}

def add_batch(raw_list, cat_id, prefix):
    for i, item in enumerate(raw_list, 1):
        word, pron, pos, meaning, ex, rom = item
        uid = f"{prefix}_{i}"
        entry = {
            "id": uid,
            "word": word,
            "pronunciation": pron,
            "category": cat_id,
            "partOfSpeech": pos,
            "meaning": meaning,
            "exampleSentence": ex,
            "romanization": rom
        }
        all_items.append(entry)
        counts[cat_id] = counts.get(cat_id, 0) + 1

add_batch(raw_food, "food", "f")
add_batch(raw_animals, "animals", "a")
add_batch(raw_body, "body", "b")
add_batch(raw_daily, "daily", "d")
add_batch(raw_travel, "travel", "t")
add_batch(raw_emotions, "emotions", "e")
add_batch(raw_jobs, "jobs", "j")
add_batch(raw_education, "education", "edu")
add_batch(raw_buddhism, "buddhism", "rel")
add_batch(raw_tricky, "tricky", "s")

print(f"Total words created: {len(all_items)}")
for c in categories:
    if c["id"] != "all":
        print(f" - {c['name']} ({c['id']}): {counts[c['id']]} คำ")

